public class Example {
    class CustomObject {
        private String name;
        public CustomObject(String name) { this.name = name; }
        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            CustomObject other = (CustomObject) obj;
            return name.equals(other.name);
        }
        @Override
        public int hashCode() {
            return name.hashCode();
        }
    }

    public boolean compareCustomObjects(CustomObject obj1, CustomObject obj2) {
        // This should not be refactored, CustomObject has its own equals method
        return obj1.equals(obj2);
    }

    public boolean compareStrings(String s1, String s2) {
        // This should not be refactored, String has its own equals method
        return s1.equals(s2);
    }
}
